from collections import deque #importamos librería FIFO necesaria

"""Ahora implementamos el grafo correspondiente:"""

grafo = {
    "Bogota": ["Tunja", "Villavicencio"],
    "Tunja": ["Duitama", "Chiquinquira"],
    "Villavicencio": ["Acacias"],
    "Duitama": ["Sogamoso"],
    "Chiquinquira": ["Zipaquira"],
    "Acacias": ["Zipaquira"],
    "Zipaquira": ["Chia"],
    "Sogamoso": [],
    "Chia": []
}

"""Parte A · Recorrido:
ejecutar BFS desde bogotá y reporte el orden completo de exploración
"""

def bfs(grafo,inicio):
  profundidades = {inicio:0} #creamos un diccionario de profundidades, donde guardaremos que profundidad tiene cada nodo
  cola = deque([(inicio,0)]) #creamos una cola con una lista
  visitados = set()
  while cola: #mientras la cola no esté vacía (mientras haya nodos los cuales visitar)
    nodo, prof_actual = cola.popleft() #extraemos el primer nodo de la cola
    if nodo not in visitados: #si el nodo no está en los visitados
      print("visitando a -> ", nodo)
      visitados.add(nodo) #lo agregamos al conjunto de visitados

      for vecino in grafo[nodo]: #iteramos sobre los vecinos del nodo, para luego
        profundidades[vecino] = prof_actual + 1 # actualizamos profundidad de los vecinos
        cola.append((vecino, prof_actual + 1)) # agregarlos a la cola
  return profundidades #retornamos las profundidades para metricas de mas adelante

profundidades = bfs(grafo,"Bogota") # guardamos las profundidades en una variable para el inciso C

"""Parte B · Ruta
•	Encuentre una ruta desde Bogota hasta Chia y reporte la secuencia de nodos.

"""

def bfs_buscar(grafo, inicio, objetivo):
  cola = deque([inicio]) #creamos una cola con una lista que almacena los nodos y sus hijos
  visitados = set() #creamos un conjunto de visitados
  camino = []
  while cola: #mientras la cola no esté vacía (mientras haya nodos los cuales visitar)
    nodo = cola.popleft() #extraemos el primer nodo de la cola
    if nodo not in visitados: #si el nodo no está en los visitados, lo visitamos
      visitados.add(nodo)
      camino.append(nodo)
      if nodo == objetivo: #si el nodo es el objetivo, terminamos la busqueda
        break
      for vecino in grafo[nodo]: #iteramos sobre los vecinos del nodo, para luego
        cola.append(vecino) # agregarlos a la cola
  if objetivo in visitados:
    print("el camino de ", inicio, " hasta ", objetivo," es: ", camino)
    return True, camino, visitados
  else:
    print("el camino de ", inicio, " hasta ", objetivo , " no existe")
    return False, None, None

encontrado, camino, visitados = bfs_buscar(grafo,"Bogota","Chia") #probamos la funcion para encontrar un camino, guardamos tambien metricas minimas

"""Parte C · Profundidad
•	Determine el nivel de cada nodo respecto a Bogota. Recuerde que Bogota pertenece al nivel 0.

"""

for i, k in profundidades.items(): #imprimimos las profundidades ordenadas por ciudad
  print(i, " : ", k)

"""Parte D · Métricas mínimas"""

def imprimir_metricas():
  metricas = {
      "ruta":camino,
      "pasos":len(camino),
      "visitados": visitados,
      "cantidad_visitados":len(visitados)
  }
  for k,v in metricas.items():
    print(k,":",v)

#probamos imprimirlos
imprimir_metricas()